p=R/'scripts/validate_project.py';s=p.read_text();s=s.replace("assert ''.join(e['character'] for e in batch['entries']) == batches['frozen_batches'][0]['main_glyphs']", "declared = next((b for b in batches['frozen_batches'] if b['id'] == batch['batch_id']), None)\n    assert declared is not None, 'Unknown batch ID'\n    assert ''.join(e['character'] for e in batch['entries']) == declared['main_glyphs']")
s=s.replace("'B01_primary_checked':len(batch['entries']),", "batch['batch_id']+'_primary_checked':len(batch['entries']),")
